import re, pathlib
hits = {}
for p in pathlib.Path('.').rglob('*'):
    if p.is_file() and '.git' not in p.parts:
        try: t = p.read_text()
        except Exception: continue
        if 'legacy_fetch' in t:
            hits[str(p)] = [l for l in t.splitlines() if 'legacy_fetch' in l and 'legacy_fetch(' not in l]
print(len(hits)); print({k:v for k,v in hits.items() if v})

